INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('6c7bbac4-7cf3-4db1-8b2d-9e4c33e0a8be', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "26fa4876-5e60-4c01-bc17-c92826ce4222", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "ee5c7f09-cc3a-42ab-bc65-92bc938838a4", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "fb98aad2-28a3-401b-8c96-dc8f6f979516", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "75edba0f-79f1-48d6-ad69-54fc053ec57f", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "decf881f-07c3-43b5-9e03-c36645196838", "text": "Igaz", "isCorrect": true}, {"id": "2cded802-8584-48ae-b0c3-feadae1fd099", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ea053fd1-b532-40df-b69b-a49588f98a83", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "a77afc3b-0cf5-4451-a701-9f5f4e804a62", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "096b5ddf-0087-4212-83d5-0f30b7baab44", "text": "Igaz", "isCorrect": true}, {"id": "f40457d2-6a57-47b9-aaa2-e1ae561265d6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "89a68067-a367-4b1d-8c6e-e7cebf9818da", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('60975e2d-26f4-47ca-9c05-2589e8b8df2c', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e660b524-e98a-4123-bf7a-ab4327cbae20", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "7ad1f56b-1da9-4938-bd03-713faa0563ae", "text": "2 : 7", "isCorrect": true}, {"id": "2a01d187-30fc-4f00-9f9d-23723462dc9b", "text": "1 : 35", "isCorrect": false}, {"id": "a0263a2a-2833-48d9-90d6-276a652c001b", "text": "2 : 5", "isCorrect": false}, {"id": "0750eb12-74f7-43e7-a9e7-6164e7fe6d90", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "733bc544-f4a6-4aca-922f-5cb5e8153da5", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "c7271300-d523-4283-bc44-b87b03894216", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "f34f1785-4aa3-40a1-878e-c0cf287d952c", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "4a275a71-898e-4c29-b413-ca4eef982f38", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "9d7d9844-aa2d-406a-bce2-d85f4512680d", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "ff904d0e-5a2b-4fe0-b4c8-7e62521ecb94", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "1f7bc894-ede5-4373-bd67-d18e542193b9", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "156db621-aa78-4555-a93d-72a637796da5", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "1d19071e-14f8-44cc-b1fc-1b22b34b5a05", "text": "Igaz", "isCorrect": true}, {"id": "255a76ae-4a4b-4aa5-ba73-d7093c705e5d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e75817e5-3b8e-492c-8d1e-a6961c934d85", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW()),
('d2ab8504-b6f8-4d35-9457-7544f1ff95ac', '21feff02-016d-46e2-bb9d-c27495133b1b', '97. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "c6a630bd-8db6-4094-bd8c-5d3ac38e681c", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "47452b47-d91b-4e25-9d5b-e8fa573301df", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "73e19c68-4f60-4171-a3e7-622bbaba211f", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "8c556aa6-7205-4985-a4df-5c9c4b90e191", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "dc2bc175-784c-4c48-b18b-1edae9d18cc7", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "8fdb7ccf-7fa7-4fe5-83f4-fdc44fb77800", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "8e2267fb-4310-43d4-b8af-facdd21fbb96", "text": "Igaz", "isCorrect": true}, {"id": "80c2dd0b-6d54-4afe-a275-7681b051ce43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f1ecb741-de8a-40c2-8992-0f06177e1e18", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "77313471-35cb-4ef4-afce-b054286514b8", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "19be3639-6133-4645-b3ae-743358ba8a67", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "cece1cad-5586-47cb-8dcb-54d8da50fdc5", "text": "Igaz", "isCorrect": true}, {"id": "f995a5d2-4029-4219-8e35-dd79cc395e05", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bfb95fab-9d8c-48c1-a278-401ca059e156", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "5ad39a87-3e55-4e07-8804-6cfde96b74d0", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('23db79cb-a69f-45d0-aeda-097a1e101c54', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f461b896-7e68-499b-b1e9-25c92f59377b", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "26f8e5ef-4797-4859-a8c3-3a9bc19d6ac6", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "90b7c390-ec9f-4d7a-9573-b174d365a340", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "8efe9eb2-c4bc-42a8-a865-f47250ac010d", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "9a86e554-fae9-46c8-ab66-2057f874ecf4", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "dec28a41-f167-4b57-8a33-d6ea281d1c8f", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "90cd2251-2155-45dc-a4c7-a7c0567f028c", "text": "Igaz", "isCorrect": true}, {"id": "9d03184b-b6b1-4dc2-9a4c-94a445863747", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "62eec457-fe9e-475a-9e72-d26aa5ff6f1a", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW()),
('aa04773d-72b8-4031-8250-fdc3f5ec361f', '21feff02-016d-46e2-bb9d-c27495133b1b', '99. óra: Hosszúság, tömeg, idő II.', 'Összetett mértékegység-átváltási feladatok és gyakorlás.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f536b8a4-10ec-43d8-9253-8da68ccb35ca", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "07b83170-832a-495a-ad5f-e99d04e2b073", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "253ab087-2979-492e-aead-900c2b193e2c", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "f6d106d0-e0ca-4899-8c00-e3214edccda2", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "8ab6de9e-e3b9-4461-b353-9efa88967d74", "text": "Igaz", "isCorrect": true}, {"id": "398e9c61-0ce4-475a-bd36-8a18a37c011a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff258cd3-ac0d-475d-b83b-a8b2ac9cb802", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "e1249acd-0377-4d4b-9c62-7b7fc92dd98a", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "5671093c-720d-4c0e-a50e-a88584d7f458", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "0bf9841b-d54f-4dd4-a8da-bc5ab07aa681", "text": "Igaz", "isCorrect": true}, {"id": "e8737a9b-3db0-4911-b1d6-7c4270ccaeb1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());